<?php
/** @noinspection PhpUnhandledExceptionInspection */
declare(strict_types=1);

// Test generated by Claude Code (with manual adjustments).

namespace Tests\Customer\Action\Command;

use Module\Customer\Action\Command\ChangeStoreCmd;
use Module\Customer\Action\Dto\ChangeStoreRequestDto;
use Module\Customer\Action\Enum\CustomerStatusEnum;
use Module\Customer\Model\Customer;
use Module\Customer\Model\CustomerRepository;
use Module\Customer\Support\CustomerBag;
use Module\Customer\Support\Security\TokenService;
use Module\Shared\Exception\AppNeverException;
use Module\Shared\Exception\AppValidationException;
use Module\Store\Action\Query\CheckStoreExistsQry;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\Attributes\Test;
use Tests\IntegrationTestCase;

class ChangeStoreCmdTest extends IntegrationTestCase
{
    private ChangeStoreCmd $sut;

    private CustomerBag $customerBag;
    private CustomerRepository $customerRepository;

    public function setUp(): void
    {
        parent::setUp();

        $this->customerRepository = $this->container->get(CustomerRepository::class);

        $checkStoreExistsQry = $this->createStub(CheckStoreExistsQry::class);
        $checkStoreExistsQry->method('check')->willReturnCallback(fn (int $id) => $id === 10);

        $tokenService = $this->createStub(TokenService::class);
        $tokenService->method('newAccessToken')->willReturn('JWT token');

        $this->customerBag = new CustomerBag();

        $this->sut = new ChangeStoreCmd(
            $checkStoreExistsQry,
            $tokenService,
            $this->customerBag,
            $this->customerRepository,
        );

        $this->prepareDb();
    }

    #[Test, DataProvider('dataProviderHandle')]
    public function handle(
        int $storeId,
        ?int $customerBagCustomerId,
        string $expectedExceptionClass,
        string $expectedExceptionMessage,
    ): void {
        $this->customerBag->customerId = $customerBagCustomerId;

        if ($expectedExceptionClass) {
            $this->expectException($expectedExceptionClass);
            $this->expectExceptionMessageMatches('/^' . preg_quote($expectedExceptionMessage, '/') . '$/');
        }

        $result = $this->sut->handle(new ChangeStoreRequestDto($storeId));

        $this->assertEquals('JWT token', $result->token);
    }

    /**
     * @return array<string, array<string, mixed>>
     */
    public static function dataProviderHandle(): array
    {
        return [
            'store not found' => [
                'storeId' => 99,
                'customerBagCustomerId' => 5,
                'expectedExceptionClass' => AppValidationException::class,
                'expectedExceptionMessage' => 'storeId: Invalid store id',
            ],
            'not authenticated' => [
                'storeId' => 10,
                'customerBagCustomerId' => null,
                'expectedExceptionClass' => AppNeverException::class,
                'expectedExceptionMessage' => 'Customer is not authenticated.',
            ],
            'customer not found' => [
                'storeId' => 10,
                'customerBagCustomerId' => 20,
                'expectedExceptionClass' => AppNeverException::class,
                'expectedExceptionMessage' => 'Customer not found.',
            ],
            'success' => [
                'storeId' => 10,
                'customerBagCustomerId' => 5,
                'expectedExceptionClass' => '',
                'expectedExceptionMessage' => '',
            ],
        ];
    }

    private function prepareDb(): void
    {
        $this->customerRepository->saveWithId(Customer::factory('cust 5', 2, CustomerStatusEnum::ACTIVE, 5));
        $this->customerRepository->flush();
    }
}
